INSERT INTO `v1_64f897564b6fd88555b71cae30b7bcbd11d826c2366cf211d57f5a9ec58db291` VALUES ("イベントでは、特別なストーリーをお楽しみいただけます。\n閲覧可能なストーリーを読むと、次のお話が解放されていきますよ。\nストーリーの閲覧によって達成されるミッションもあるのだとか。", 1, 1, 1011, 1);
INSERT INTO `v1_64f897564b6fd88555b71cae30b7bcbd11d826c2366cf211d57f5a9ec58db291` VALUES ("イベントクエストやボスバトルに挑戦してみましょう。ボスバトルは\n特定のイベントストーリーを閲覧するか、イベントクエスト・ボス画面で\n「解放する」を選択すると挑戦可能になりますよ。", 2, 1, 1021, 2);
INSERT INTO `v1_64f897564b6fd88555b71cae30b7bcbd11d826c2366cf211d57f5a9ec58db291` VALUES ("報酬交換では「イベント報酬券」と様々なアイテムを交換できます。\n目玉となるリセット対象報酬を引くことで、より多くのアイテムが\n獲得できる次のラインナップへと進めるそうです。", 4, 1, 1041, 4);
INSERT INTO `v1_64f897564b6fd88555b71cae30b7bcbd11d826c2366cf211d57f5a9ec58db291` VALUES ("ボスバトルには３種の難易度がございます。\n各難易度ごとにボスの強さやバトルの特徴が異なりますので、\n準備をしっかりして、気を引き締めて挑みましょう。", 5, 1, 1051, 5);
INSERT INTO `v1_64f897564b6fd88555b71cae30b7bcbd11d826c2366cf211d57f5a9ec58db291` VALUES ("イベントでは、特別なストーリーをお楽しみいただけます。\n閲覧可能なストーリーを読むと、次のお話が解放されていきますよ。", 1, 2, 2011, 1);
INSERT INTO `v1_64f897564b6fd88555b71cae30b7bcbd11d826c2366cf211d57f5a9ec58db291` VALUES ("イベントクエストやボスバトルに挑戦してみましょう。ボスバトルは\n特定のイベントストーリーを閲覧するか、イベントクエスト・ボス画面で\n「解放する」を選択すると挑戦可能になりますよ。", 2, 2, 2021, 2);
INSERT INTO `v1_64f897564b6fd88555b71cae30b7bcbd11d826c2366cf211d57f5a9ec58db291` VALUES ("報酬交換では「イベント報酬券」と様々なアイテムを交換できます。\n目玉となるリセット対象報酬を引くことで、より多くのアイテムが\n獲得できる次のラインナップへと進めるそうです。", 4, 2, 2041, 4);
INSERT INTO `v1_64f897564b6fd88555b71cae30b7bcbd11d826c2366cf211d57f5a9ec58db291` VALUES ("ボスバトルには２種の難易度がございます。\n各難易度ごとにボスの強さやバトルの特徴が異なりますので、\n準備をしっかりして、気を引き締めて挑みましょう。", 5, 2, 2051, 5);
